class Solution {
    public int largestPalindrome(int n) {
        if (n == 1) return 9; // given in problem

        long max = (long) Math.pow(10, n) - 1;
        long min = (long) Math.pow(10, n - 1);

        // For n > 1, largest palindrome can be constructed from the half
        // We generate palindrome from higher half and check if product factors exist
        for (long left = max; left >= min; left--) {
            // Create palindrome by appending reverse of left
            // Example: left = 123, palindrome = 123321
            long palindrome = createPalindrome(left);

            // Try to find factors i, j of palindrome, both n-digit
            // i starts from max down to min for efficiency
            for (long i = max; i * i >= palindrome; i--) {
                if (palindrome % i == 0) {
                    long j = palindrome / i;
                    if (j >= min && j <= max) {
                        return (int)(palindrome % 1337);
                    }
                }
            }
        }

        return 0;
    }

    // create palindrome by appending reverse of left to left
    private long createPalindrome(long left) {
        String leftStr = Long.toString(left);
        StringBuilder sb = new StringBuilder(leftStr);
        String rev = sb.reverse().toString();
        sb.reverse();  // revert back
        return Long.parseLong(leftStr + rev);
    }
}

